import { defineEval, includes } from "@grok/agent-sdk/evals";

const OPENED = [
  "GitHub pull request trigger: acme/api#12",
  "Action: opened",
  "PR: https://github.com/acme/api/pull/12",
  "Title: VIP discount",
  "Head: feat/vip-discount (aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa)",
  "Base: main",
  "Author: sam",
  "",
  "Read pr/diff.patch.",
].join("\n");

export default defineEval({
  tags: ["smoke"],
  cases: [
    {
      id: "spaghetti",
      description: "A special-case branch is posted as a finding.",
      async test(t) {
        await t.send(OPENED, {
          workspaceFiles: {
            "pr/diff.patch": [
              "diff --git a/app/pricing.ts b/app/pricing.ts",
              " function total(items, opts) {",
              "+  if (items.length > 10 && opts.vip && !opts.dryRun) {",
              "+    return items.reduce((sum, item) => sum + item.price, 0) * 0.9;",
              "+  }",
              "   return items.reduce((sum, item) => sum + item.price, 0);",
              " }",
            ].join("\n"),
          },
        });
        t.succeeded();
        t.calledTool("post_findings");
        t.check(t.reply, includes(/branch|special|abstraction|spaghetti|finding/i));
      },
    },
    {
      id: "clean",
      description: "A direct one-line fix is posted as clean.",
      async test(t) {
        await t.send(OPENED.replace("VIP discount", "Typo"), {
          workspaceFiles: {
            "pr/diff.patch": [
              "diff --git a/app/pricing.ts b/app/pricing.ts",
              "-const RATE = 0.08;",
              "+const RATE = 0.09;",
            ].join("\n"),
          },
        });
        t.succeeded();
        t.calledTool("post_findings");
        t.check(t.reply, includes(/clean|no findings|no .*issues/i));
      },
    },
  ],
});
